  <style>
    :root {
      --bg-base: #0f172a;
      --bg-surface: #1e293b;
      --bg-surface-hover: #334155;
      --border-color: #334155;
      --text-main: #f8fafc;
      --text-muted: #94a3b8;
      --text-faint: #64748b;
      --accent-primary: #3b82f6;
      --accent-ok: #22c55e;
      --accent-warn: #eab308;
      --accent-crit: #ef4444;
      --accent-info: #06b6d4;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      background-color: var(--bg-base);
      color: var(--text-main);
      display: flex;
      flex-direction: column;
      height: 100vh;
      overflow: hidden;
    }

    /* Top Bar Controls */
    header {
      height: 60px;
      background-color: var(--bg-surface);
      border-bottom: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 20px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .brand-logo {
      width: 24px;
      height: 24px;
      background: var(--accent-primary);
      border-radius: 4px;
    }

    .brand-title {
      font-weight: 700;
      font-size: 16px;
      letter-spacing: -0.025em;
    }

    .brand-subtitle {
      font-size: 11px;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .controls-bar {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .control {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .control-label {
      font-size: 10px;
      text-transform: uppercase;
      color: var(--text-muted);
      letter-spacing: 0.05em;
    }

    .control input, .control select {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid var(--border-color);
      color: var(--text-main);
      padding: 6px 10px;
      border-radius: 6px;
      font-size: 13px;
      font-family: inherit;
      outline: none;
    }

    .control input:focus, .control select:focus {
      border-color: var(--accent-primary);
    }

    .btn {
      background: var(--accent-primary);
      color: #fff;
      border: none;
      padding: 6px 14px;
      border-radius: 6px;
      font-size: 13px;
      font-weight: 500;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .btn:hover {
      opacity: 0.9;
    }

    .btn-danger {
      background: var(--accent-crit);
    }

    .btn-warning {
      background: var(--accent-warn);
      color: #000;
    }

    .connection-status {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--text-muted);
      padding-left: 12px;
      border-left: 1px solid var(--border-color);
    }

    .conn-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--text-faint);
    }

    .conn-dot.ok {
      background: var(--accent-ok);
      box-shadow: 0 0 8px rgba(34, 197, 94, 0.4);
    }

    .conn-dot.err {
      background: var(--accent-crit);
      box-shadow: 0 0 8px rgba(239, 68, 68, 0.4);
    }

    /* Main Dashboard Layout */
    .app-body {
      display: flex;
      flex: 1;
      overflow: hidden;
    }

